                    res.append((start, i))
                    start = None
            else:
                if start is None:
                    start = i
        if start is not None:
            res.append((start, n))
        return res

    row_groups = groups(h, sep_rows)
    col_groups = groups(w, sep_cols)

    # Map each cell to its block row/col
    row_to_group = {}
    for gi, (a, b) in enumerate(row_groups):
        for r in range(a, b):
